"""Cybersecurity glossary, part 12: more attack methods, famous malware and vulnerabilities. Same row format as cyber_terms_1.py, built with the helper T().
Descriptions are protective (what it is, how to recognise and resist), never instructions for attacking. fr/rw/sw are drafts for fluent review."""


def T(id_, en, aliases, cat, photo, local, E, F, R, S):
    """E/F/R/S = (meaning, use) in English, French, Kinyarwanda, Kiswahili."""
    return (id_, en, aliases, cat, photo, local, E[0], E[1], F[0], F[1], R[0], R[1], S[0], S[1])


TERMS_12 = [
    T("wallet-drainer", "Wallet drainer", ["wallet drainer", "crypto drainer", "crypto airdrop scam", "approve transaction scam"], "attacks", "cryptocurrency wallet", {"fr": "Siphon de portefeuille crypto", "sw": "Kumwaga pochi ya crypto", "rw": "Gusahura wallet ya crypto"},
      ("A malicious website or app that tricks you into approving a crypto transaction or connecting your wallet, so the attacker can move your coins.", "Often promoted as a free airdrop or giveaway. Never connect a wallet to a site you reached from a message, and read what a transaction approves before you sign."),
      ("Un site ou une application malveillants qui vous poussent à approuver une transaction ou connecter votre portefeuille pour que l'attaquant déplace vos cryptomonnaies.", "Souvent présenté comme un airdrop ou cadeau gratuit. Ne connectez jamais votre portefeuille à un site reçu par message et lisez ce que la transaction autorise avant de signer."),
      ("Urubuga cyangwa porogaramu mbi ikuriganya ukemeza igikorwa cya crypto cyangwa ugahuza wallet yawe, umushimusi agahita yimura amafaranga yawe.", "Akenshi bavuga ko ari airdrop cyangwa impano y'ubuntu. Ntuzigere uhuza wallet yawe n'urubuga wahawe mu butumwa kandi usome icyo igikorwa cyemeza mbere yo gusinya."),
      ("Tovuti au programu hasidi inayokudanganya uidhinishe muamala wa crypto au kuunganisha pochi yako ili mshambulizi ahamishe sarafu zako.", "Mara nyingi hutangazwa kama airdrop au zawadi ya bure. Kamwe usiunganishe pochi yako na tovuti ulioipata kwa ujumbe, na soma kile muamala unachoidhinisha kabla ya kusaini.")),
    T("clipboard-hijacking", "Clipboard hijacking", ["clipboard hijacking", "clipboard hijacker", "address swapper", "clipper malware", "crypto clipper"], "malware", "copy and paste on computer", {"fr": "Détournement du presse-papiers", "sw": "Kuteka ubao wa kunakili", "rw": "Gutwara clipboard"},
      ("Malware that silently replaces something you copied, such as a bank or crypto wallet address, with the attacker's own address.", "You paste and send money to the wrong person. Always compare the first and last characters of an account or wallet address after pasting, and keep devices clean."),
      ("Un logiciel malveillant qui remplace discrètement ce que vous avez copié, comme une adresse bancaire ou de portefeuille crypto, par celle de l'attaquant.", "Vous collez et envoyez l'argent à la mauvaise personne. Comparez toujours le début et la fin de l'adresse après le collage et gardez vos appareils propres."),
      ("Malware ihindura rwihishwa icyo wakopeye, nk'aderesi ya konti cyangwa wallet ya crypto, ikayisimbuza iy'umushimusi.", "Wandukura ukohereza amafaranga ku muntu utari we. Buri gihe gereranya imbere n'inyuma by'aderesi umaze kuyandukura kandi ugumishe ibikoresho byawe bisukuye."),
      ("Programu hasidi inayobadilisha kimya kimya ulichonakili, kama anwani ya benki au pochi ya crypto, na anwani ya mshambulizi.", "Unabandika na kutuma pesa kwa mtu mbaya. Linganisha kila mara mwanzo na mwisho wa anwani baada ya kubandika na uweke vifaa vyako safi.")),
    T("atm-card-trapping", "ATM card trapping", ["atm card trapping", "card trapping", "lebanese loop", "atm trap", "atm card stuck scam"], "attacks", "ATM cash machine", {"fr": "Piégeage de carte au distributeur", "sw": "Kunasa kadi ya ATM", "rw": "Guta ikarita muri ATM"},
      ("A device placed in an ATM card slot that keeps your card inside, while a helper offers to “help” and watches or tricks you into revealing your PIN.", "If your card gets stuck, never accept help from a stranger or tell anyone your PIN. Call your bank from a safe place, block the card, and use ATMs inside bank branches."),
      ("Un dispositif posé dans la fente du distributeur qui retient votre carte, pendant qu'un complice propose de « vous aider » et observe ou vous fait révéler votre code PIN.", "Si votre carte reste bloquée, n'acceptez jamais l'aide d'un inconnu et ne dites votre PIN à personne. Appelez votre banque d'un lieu sûr, bloquez la carte et préférez les distributeurs dans les agences."),
      ("Igikoresho gishyirwa mu mwanya w'ikarita muri ATM kikagumana ikarita yawe, mu gihe umufasha avuga ko agufasha akareba cyangwa akakuriganya ngo uvuge PIN.", "Ikarita yawe nifata, ntukemere ubufasha bw'umuntu utazi kandi ntuzigere ubwira PIN umuntu. Hamagara banki yawe uri ahantu hizewe, uhagarike ikarita kandi ukoreshe ATM ziri mu mashami ya banki."),
      ("Kifaa kinachowekwa kwenye sehemu ya kadi ya ATM kikibakiza kadi yako ndani, huku msaidizi akijifanya kukusaidia na kuangalia au kukudanganya utoe PIN.", "Kadi ikikwama, usikubali msaada wa mgeni wala kumwambia PIN. Piga benki yako ukiwa mahali salama, zuia kadi na utumie ATM zilizo ndani ya matawi ya benki.")),
    T("atm-jackpotting", "ATM jackpotting", ["jackpotting", "atm jackpotting", "atm malware", "cash out attack"], "attacks", "ATM cash machine", {"fr": "Jackpotting de distributeur", "sw": "ATM jackpotting", "rw": "ATM jackpotting"},
      ("An attack on the cash machine itself (using malware or hardware access) that forces it to dispense cash without any card or account being debited.", "A risk for banks and ATM owners rather than card holders. Defences: locked and alarmed cabinets, patched ATM software, application allow-listing and monitoring for unusual cash dispensing."),
      ("Une attaque contre le distributeur lui-même (par logiciel malveillant ou accès matériel) qui le force à distribuer des billets sans carte ni compte débité.", "Un risque pour les banques et propriétaires de distributeurs plus que pour les porteurs de carte. Défenses : coffres verrouillés avec alarme, logiciels à jour, liste blanche d'applications et surveillance des retraits anormaux."),
      ("Igitero kibasira ATM ubwayo (hakoreshejwe malware cyangwa kugera ku bikoresho) gituma isohora amafaranga nta karita cyangwa konti iciwe.", "Ni ikibazo ku mabanki na ba nyiri ATM kurusha abafite amakarita. Uburyo bwo kwirinda: ibyuma bifunze bifite alarm, porogaramu zivuguruye, urutonde rw'porogaramu zemewe no gukurikirana amafaranga asohoka mu buryo budasanzwe."),
      ("Shambulio kwa mashine ya ATM yenyewe (kwa programu hasidi au ufikiaji wa vifaa) linalolazimisha itoe pesa bila kadi wala akaunti kukatwa.", "Hatari kwa benki na wamiliki wa ATM zaidi ya wenye kadi. Ulinzi: makabati yaliyofungwa yenye kengele, programu zilizosasishwa, orodha ya programu zinazoruhusiwa na kufuatilia utoaji pesa usio wa kawaida.")),
    T("sim-cloning", "SIM cloning", ["sim cloning", "sim clone", "cloned sim", "clone sim card"], "attacks", "SIM card", {"fr": "Clonage de carte SIM", "sw": "Kunakili SIM kadi", "rw": "Gukopera SIM karita"},
      ("Copying the identity data of a SIM card onto another one so that calls, texts and verification codes can reach the attacker. It is different from SIM swap, where the operator is tricked into moving your number.", "Warning signs: sudden loss of signal, codes you did not request, unknown activity. Contact your operator at once, ask for a new SIM and protect accounts with an authenticator app instead of SMS codes."),
      ("Copier les données d'identité d'une carte SIM sur une autre pour que appels, SMS et codes de vérification parviennent à l'attaquant. Différent du SIM swap, où l'on trompe l'opérateur pour déplacer votre numéro.", "Signes d'alerte : perte soudaine de réseau, codes non demandés, activité inconnue. Contactez immédiatement votre opérateur, demandez une nouvelle SIM et protégez vos comptes avec une application d'authentification plutôt que par SMS."),
      ("Gukopera amakuru y'umwirondoro wa SIM karita ku yindi kugira ngo ibyo guhamagara, SMS na kode zo kwemeza bigere ku mushimusi. Binyuranye na SIM swap aho bariganya sosiyete ya telefone ngo yimure nimero yawe.", "Ibimenyetso: gutakaza murandasi cyangwa signal ako kanya, kode utasabye, ibikorwa utazi. Hamagara sosiyete yawe ya telefone vuba, usabe SIM nshya kandi urinde konti zawe ukoresheje porogaramu ya authenticator aho gukoresha kode za SMS."),
      ("Kunakili data ya utambulisho wa SIM kadi kwenye nyingine ili simu, SMS na misimbo ya uthibitisho zimfikie mshambulizi. Tofauti na SIM swap ambapo kampuni ya simu hudanganywa ihamishe namba yako.", "Dalili: kupoteza mtandao ghafla, misimbo usiyoomba, shughuli zisizojulikana. Wasiliana na kampuni ya simu mara moja, omba SIM mpya na linda akaunti kwa programu ya authenticator badala ya misimbo ya SMS.")),
    T("ussd-fraud", "USSD fraud", ["ussd fraud", "ussd scam", "dial code scam", "ussd code scam", "star code scam"], "attacks", "mobile phone keypad", {"fr": "Fraude par code USSD", "sw": "Ulaghai wa USSD", "rw": "Uburiganya bukoresheje USSD"},
      ("Tricking you into dialling a USSD code (like *123#) that secretly activates call forwarding, sends money or approves a transfer.", "Never dial a code someone dictates over the phone or in a message. Check what a code does on your operator's official page and set a mobile-money PIN you never share."),
      ("Vous pousser à composer un code USSD (comme *123#) qui active en secret le renvoi d'appel, envoie de l'argent ou approuve un transfert.", "Ne composez jamais un code dicté par téléphone ou message. Vérifiez ce qu'il fait sur la page officielle de l'opérateur et gardez un PIN mobile money que vous ne partagez pas."),
      ("Kukuriganya ngo ukande kode ya USSD (nka *123#) ikora rwihishwa, igafungura guhindura ahoherezwa ubutumwa, igohereza amafaranga cyangwa ikemeza kohereza.", "Ntuzigere ukanda kode umuntu akubwiye kuri telefone cyangwa mu butumwa. Reba icyo kode ikora ku rubuga rwemewe rwa sosiyete ya telefone kandi ugire PIN ya mobile money utagira undi."),
      ("Kukudanganya upige msimbo wa USSD (kama *123#) unaowasha kimya kimya upelekaji simu, kutuma pesa au kuidhinisha uhamisho.", "Kamwe usipige msimbo unaoambiwa kwa simu au ujumbe. Angalia unachofanya kwenye ukurasa rasmi wa kampuni ya simu na uwe na PIN ya pesa za simu usiyoshiriki.")),
    T("tabnabbing", "Tabnabbing", ["tabnabbing", "reverse tabnabbing", "tab napping"], "attacks", "web browser tabs", {"fr": "Tabnabbing (détournement d'onglet)", "sw": "Tabnabbing", "rw": "Tabnabbing"},
      ("A phishing trick where a page you left open in a browser tab quietly changes itself into a fake login page while you are busy elsewhere.", "Before typing a password into a tab you left open, check the address bar and the padlock, or open the site again yourself. Developers should use rel=\"noopener\" on external links."),
      ("Une ruse de phishing où une page laissée ouverte dans un onglet se transforme discrètement en fausse page de connexion pendant que vous faites autre chose.", "Avant de saisir un mot de passe dans un onglet resté ouvert, vérifiez la barre d'adresse et le cadenas, ou rouvrez vous-même le site. Les développeurs doivent mettre rel=\"noopener\" sur les liens externes."),
      ("Uburiganya bwa phishing aho urupapuro warekeye rufunguye muri tab rwihinduranya rwihishwa rukaba urupapuro rw'impimbano rwo kwinjira mu gihe ukora ibindi.", "Mbere yo kwandika ijambo ry'ibanga muri tab warekeye ifunguye, reba aderesi n'agakingirizo cyangwa ufungure urubuga ubwawe. Abategura porogaramu bakoreshe rel=\"noopener\" ku mahuza yo hanze."),
      ("Hila ya hadaa ambapo ukurasa ulioacha wazi kwenye kichupo hubadilika kimya kimya kuwa ukurasa bandia wa kuingia ukiwa unafanya mambo mengine.", "Kabla ya kuandika nenosiri kwenye kichupo ulichoacha wazi, angalia upau wa anwani na kufuli au fungua tovuti upya mwenyewe. Wasanidi watumie rel=\"noopener\" kwenye viungo vya nje.")),
    T("email-bombing", "Email bombing", ["email bombing", "mail bombing", "subscription bombing", "inbox flooding"], "attacks", "email inbox overflow", {"fr": "Bombardement d'e-mails", "sw": "Mafuriko ya barua pepe", "rw": "Gusenya inbox n'imeri nyinshi"},
      ("Flooding a mailbox with thousands of emails, often by signing the victim up to many newsletters, to bury a real alert such as a bank warning or password reset.", "If your inbox suddenly fills with sign-up messages, check your bank and account alerts right away, because a fraud may be happening at the same time. Use mail filters and report to your provider."),
      ("Inonder une boîte mail de milliers de messages, souvent en inscrivant la victime à de nombreuses lettres d'information, pour noyer une vraie alerte comme un avertissement de la banque.", "Si votre boîte se remplit soudain de messages d'inscription, vérifiez aussitôt les alertes de votre banque et de vos comptes : une fraude peut se produire en même temps. Utilisez des filtres et signalez à votre fournisseur."),
      ("Gusuka inbox imeri ibihumbi, akenshi bandikisha uwo bibasiye ku makuru menshi, kugira ngo bahishe ubutumwa nyakuri nk'uburira bwa banki.", "Inbox yawe nitangira kuzura ubutumwa bwo kwiyandikisha ako kanya, reba ubutumwa bwa banki na konti zawe, kuko uburiganya bushobora kuba bukorwa icyo gihe. Koresha filters kandi umenyeshe utanga imeri."),
      ("Kujaza sanduku la barua pepe maelfu ya ujumbe, mara nyingi kwa kumsajili mwathirika kwenye majarida mengi, ili kuficha tahadhari halisi kama onyo la benki.", "Sanduku lako likijaa ghafla ujumbe wa kujisajili, angalia mara moja tahadhari za benki na akaunti zako, kwa sababu ulaghai unaweza kuwa unafanyika. Tumia vichujio na uripoti kwa mtoa huduma.")),
    T("code-injection", "Code injection", ["code injection", "script injection", "template injection", "injection attack", "injection attacks"], "appsec", "source code on screen", {"fr": "Injection de code", "sw": "Kuingiza msimbo (injection)", "rw": "Kwinjiza code (injection)"},
      ("The family of attacks where an attacker's text is treated by the program as instructions: SQL injection, command injection, script injection and template injection are all examples.", "Prevent by never mixing user input with code: use parameterised queries, safe template engines, input validation, output encoding and least-privilege accounts. Injection stays near the top of the OWASP Top 10."),
      ("La famille d'attaques où le texte de l'attaquant est traité par le programme comme des instructions : injection SQL, de commandes, de scripts et de modèles en sont des exemples.", "On l'évite en ne mélangeant jamais les entrées utilisateur et le code : requêtes paramétrées, moteurs de modèles sûrs, validation, encodage des sorties et comptes à privilèges minimaux. L'injection reste en tête de l'OWASP Top 10."),
      ("Ni itsinda ry'ibitero aho inyandiko y'umushimusi ifatwa na porogaramu nk'amabwiriza: SQL injection, command injection, script injection na template injection ni ingero.", "Wirinda utavanga ibyo umukoresha yinjije na code: koresha parameterised queries, template engines zizewe, kugenzura ibyinjijwe, encoding y'ibisohoka na konti zifite uburenganzira bukeya. Injection ikomeje kuba mu bya mbere muri OWASP Top 10."),
      ("Familia ya mashambulizi ambapo maandishi ya mshambulizi hutendewa na programu kama amri: SQL injection, command injection, script injection na template injection ni mifano.", "Zuia kwa kutochanganya ingizo la mtumiaji na msimbo: tumia hoja zenye vigezo, injini salama za violezo, kuhakiki ingizo, usimbaji wa matokeo na akaunti zenye haki ndogo. Injection bado ni ya juu kwenye OWASP Top 10.")),
    T("process-injection", "Process injection", ["process injection", "dll injection", "process hollowing", "code injection into process"], "attacks", "computer processes", {"fr": "Injection de processus", "sw": "Kuingiza msimbo kwenye mchakato", "rw": "Kwinjiza code mu process"},
      ("A technique where malware runs its code inside another, trusted program's memory so that it looks like normal software and is harder for antivirus to spot.", "Defenders use EDR tools that watch for unusual behaviour (not just file names), keep systems patched, restrict admin rights and allow only approved applications."),
      ("Technique où un logiciel malveillant exécute son code dans la mémoire d'un autre programme de confiance pour paraître normal et échapper plus facilement à l'antivirus.", "Les défenseurs utilisent des outils EDR qui surveillent les comportements inhabituels (pas seulement les noms de fichiers), tiennent les systèmes à jour, limitent les droits admin et n'autorisent que les applications approuvées."),
      ("Uburyo malware ikoresha code yayo mu bubiko bwa porogaramu yizewe kugira ngo isa n'isanzwe kandi antivirus igorwe kuyibona.", "Abarinzi bakoresha EDR zireba imyitwarire idasanzwe (si amazina ya dosiye gusa), bakavugurura sisitemu, bagabanya uburenganzira bwa admin kandi bakemera porogaramu zemewe gusa."),
      ("Mbinu ambapo programu hasidi huendesha msimbo wake ndani ya kumbukumbu ya programu nyingine inayoaminika ili ionekane ya kawaida na antivirus ishindwe kuigundua.", "Walinzi hutumia zana za EDR zinazoangalia tabia isiyo ya kawaida (si majina ya faili tu), husasisha mifumo, hupunguza haki za admin na kuruhusu programu zilizoidhinishwa tu.")),
    T("sandbox-escape", "Sandbox escape", ["sandbox escape", "browser escape", "vm escape", "virtual machine escape", "container escape"], "attacks", "virtual machine isolation", {"fr": "Évasion de bac à sable", "sw": "Kutoroka sandbox", "rw": "Gusohoka muri sandbox"},
      ("When an attack breaks out of an isolated environment (a browser sandbox, virtual machine or container) and reaches the real system underneath.", "Isolation is a layer, not a guarantee. Keep browsers, hypervisors and container runtimes updated, run containers with minimal privileges and separate sensitive workloads."),
      ("Quand une attaque sort d'un environnement isolé (bac à sable du navigateur, machine virtuelle ou conteneur) et atteint le vrai système en dessous.", "L'isolation est une couche, pas une garantie. Mettez à jour navigateurs, hyperviseurs et moteurs de conteneurs, exécutez les conteneurs avec le minimum de privilèges et séparez les charges sensibles."),
      ("Iyo igitero gisohoka mu mwanya watandukanyijwe (sandbox ya browser, virtual machine cyangwa container) kikagera kuri sisitemu nyayo.", "Gutandukanya ni urwego rumwe, si ingwate. Vugurura browser, hypervisor na container runtime, ukoreshe container zifite uburenganzira bukeya kandi utandukanye imirimo y'ingenzi."),
      ("Wakati shambulio linapovunja mazingira yaliyotengwa (sandbox ya kivinjari, mashine pepe au kontena) na kufikia mfumo halisi chini yake.", "Kutenga ni safu moja, si dhamana. Sasisha vivinjari, hypervisor na kontena, endesha kontena kwa haki ndogo na tenga kazi nyeti.")),
    T("cold-boot-attack", "Cold boot attack", ["cold boot attack", "ram dump attack", "memory remanence"], "attacks", "computer memory chip", {"fr": "Attaque par démarrage à froid", "sw": "Cold boot attack", "rw": "Cold boot attack"},
      ("An attack that reads encryption keys still lingering in a computer's memory just after it is switched off or rebooted, using physical access to the machine.", "Shows why physical security matters. Shut laptops down fully (not just sleep) when travelling, use a TPM with a boot PIN, and keep sensitive devices out of untrusted hands."),
      ("Une attaque qui lit les clés de chiffrement encore présentes en mémoire juste après l'extinction ou le redémarrage d'un ordinateur, grâce à un accès physique à la machine.", "Montre l'importance de la sécurité physique. Éteignez complètement les portables en déplacement (pas seulement la veille), utilisez un TPM avec PIN de démarrage et gardez les appareils sensibles hors de mains non fiables."),
      ("Igitero gisoma imfunguzo za encryption zikiri mu bubiko bwa mudasobwa nyuma gato y'uko izimwa cyangwa yongera gutangira, hakoreshejwe kuyigeraho ku mubiri.", "Cyerekana impamvu umutekano ku mubiri ari ingenzi. Zimya mudasobwa igendanwa burundu (si sleep gusa) iyo ugenda, koresha TPM na PIN yo gutangira kandi ubike ibikoresho by'ingenzi kure y'abatizewe."),
      ("Shambulio linalosoma funguo za usimbaji zilizobaki kwenye kumbukumbu ya kompyuta mara baada ya kuzimwa au kuwashwa upya, kwa kufikia mashine kimwili.", "Linaonyesha kwa nini usalama wa kimwili ni muhimu. Zima kompyuta mpakato kabisa (si sleep tu) unaposafiri, tumia TPM na PIN ya kuwasha na weka vifaa nyeti mbali na wasioaminika.")),
    T("wannacry", "WannaCry", ["wannacry", "wanna cry", "wannacrypt", "2017 ransomware worm"], "malware", "ransomware warning screen", {"fr": "WannaCry", "sw": "WannaCry", "rw": "WannaCry"},
      ("A ransomware worm that spread across the world in May 2017, locking files on hundreds of thousands of computers (including hospitals) by exploiting a flaw in old Windows file sharing for which a patch already existed.", "The lesson: install security updates promptly, retire unsupported systems and keep offline backups. It is the standard example of why patching matters."),
      ("Un ver rançongiciel qui s'est propagé dans le monde en mai 2017, bloquant les fichiers de centaines de milliers d'ordinateurs (dont des hôpitaux) via une faille du partage de fichiers de vieux Windows, pour laquelle un correctif existait déjà.", "La leçon : installer vite les mises à jour, retirer les systèmes non supportés et garder des sauvegardes hors ligne. C'est l'exemple classique de l'importance des correctifs."),
      ("Ni worm ya ransomware yakwirakwiye ku isi muri Gicurasi 2017, ifunga dosiye ku mudasobwa amagana y'ibihumbi (harimo ibitaro) ikoresheje intege nke mu gusangira dosiye kwa Windows ishaje, kandi gukosora byari bihari.", "Isomo: shyiraho ivugurura ry'umutekano vuba, reka gukoresha sisitemu zitagishyigikiwe kandi ubike kopi zitari kuri interineti. Ni urugero rw'ingenzi rw'impamvu kuvugurura ari ngombwa."),
      ("Worm ya ransomware iliyosambaa dunia nzima Mei 2017, ikifunga faili kwenye mamia ya maelfu ya kompyuta (pamoja na hospitali) kupitia udhaifu wa kushiriki faili wa Windows ya zamani ambao kiraka kilikuwepo tayari.", "Funzo: sakinisha masasisho ya usalama haraka, acha mifumo isiyoungwa mkono na uweke nakala rudufu nje ya mtandao. Ni mfano wa kawaida wa umuhimu wa viraka.")),
    T("mirai-botnet", "Mirai botnet", ["mirai", "mirai botnet", "iot botnet", "mirai malware"], "malware", "internet of things devices", {"fr": "Botnet Mirai", "sw": "Botnet ya Mirai", "rw": "Botnet ya Mirai"},
      ("Malware that took over hundreds of thousands of internet-connected cameras and routers by trying factory-default passwords, then used them in huge DDoS attacks (2016).", "The lesson for everyone with smart devices: change default passwords on routers and cameras, update firmware, and do not expose device admin pages to the internet."),
      ("Un logiciel malveillant qui a pris le contrôle de centaines de milliers de caméras et routeurs connectés en essayant les mots de passe d'usine, puis les a utilisés dans d'énormes attaques DDoS (2016).", "La leçon pour tous les possesseurs d'objets connectés : changez les mots de passe par défaut des routeurs et caméras, mettez le firmware à jour et n'exposez pas les pages d'administration sur internet."),
      ("Malware yafashe amakamera na router amagana y'ibihumbi bihujwe na interineti igerageza amagambo y'ibanga y'uruganda, hanyuma iyakoresha mu bitero bikomeye bya DDoS (2016).", "Isomo ku bafite ibikoresho bigezweho: hindura amagambo y'ibanga ya router na kamera, uvugurure firmware kandi ntugaragaze pages za admin kuri interineti."),
      ("Programu hasidi iliyodhibiti mamia ya maelfu ya kamera na router zilizounganishwa mtandaoni kwa kujaribu nywila za kiwanda, kisha kuzitumia kwenye mashambulizi makubwa ya DDoS (2016).", "Funzo kwa wote wenye vifaa janja: badilisha nywila za kiwanda za router na kamera, sasisha firmware na usiweke kurasa za usimamizi wazi mtandaoni.")),
    T("heartbleed", "Heartbleed", ["heartbleed", "openssl heartbleed", "cve-2014-0160"], "appsec", "padlock and heart", {"fr": "Heartbleed", "sw": "Heartbleed", "rw": "Heartbleed"},
      ("A 2014 flaw in the OpenSSL library that let attackers read chunks of a server's memory, which could include passwords and private keys, without leaving obvious traces.", "It showed that even encryption software can have bugs. Organisations had to patch, replace certificates and ask users to change passwords. Keep libraries updated and rotate keys after a leak."),
      ("Une faille de 2014 dans la bibliothèque OpenSSL qui permettait de lire des morceaux de la mémoire d'un serveur, pouvant contenir mots de passe et clés privées, sans laisser de trace évidente.", "Elle a montré que même un logiciel de chiffrement peut avoir des bogues. Il a fallu corriger, remplacer les certificats et demander aux utilisateurs de changer leurs mots de passe. Mettez les bibliothèques à jour et renouvelez les clés après une fuite."),
      ("Intege nke yo muri 2014 muri OpenSSL zatumaga abashimusi basoma ibice by'ubwenge bwa seriveri, bishobora kuba birimo amagambo y'ibanga n'imfunguzo, nta kimenyetso gisobanutse basize.", "Yerekanye ko na porogaramu za encryption zishobora kugira amakosa. Amashyirahamwe yagombaga gukosora, gusimbuza certificates no gusaba abakoresha guhindura amagambo y'ibanga. Vugurura library kandi uhindure imfunguzo nyuma y'ikimenyetso cyo kumeneka."),
      ("Udhaifu wa 2014 kwenye maktaba ya OpenSSL uliowaruhusu washambuliaji kusoma vipande vya kumbukumbu ya seva, vikiwemo nywila na funguo za faragha, bila alama wazi.", "Ilionyesha hata programu za usimbaji zinaweza kuwa na hitilafu. Mashirika yalilazimika kurekebisha, kubadilisha vyeti na kuwaomba watumiaji kubadilisha nywila. Sasisha maktaba na ubadilishe funguo baada ya uvujaji.")),
    T("log4shell", "Log4Shell", ["log4shell", "log4j", "log4j vulnerability", "cve-2021-44228"], "appsec", "software logs on screen", {"fr": "Log4Shell", "sw": "Log4Shell", "rw": "Log4Shell"},
      ("A critical 2021 flaw in Log4j, a Java logging library used in a vast number of products, which let an attacker run code on a server just by getting a crafted text written to its logs.", "It showed the danger of hidden dependencies. Keep an inventory of software components (SBOM), apply vendor patches quickly and use a WAF and monitoring while patching."),
      ("Une faille critique de 2021 dans Log4j, bibliothèque Java de journalisation présente dans un très grand nombre de produits, qui permettait d'exécuter du code sur un serveur rien qu'en faisant écrire un texte piégé dans ses journaux.", "Elle a montré le danger des dépendances cachées. Tenez un inventaire des composants logiciels (SBOM), appliquez vite les correctifs et utilisez un WAF et une surveillance pendant la correction."),
      ("Intege nke ikomeye yo muri 2021 muri Log4j, library ya Java yandika logs ikoreshwa mu bicuruzwa byinshi cyane, yatumaga umushimusi akoresha code kuri seriveri gusa mu gutuma inyandiko yateguwe yandikwa muri logs.", "Yerekanye ibyago by'ibikoresho byihishe muri porogaramu. Bika urutonde rw'ibice bya porogaramu (SBOM), shyiraho ibikosorwa vuba kandi ukoreshe WAF no gukurikirana mu gihe ukosora."),
      ("Udhaifu mkubwa wa 2021 kwenye Log4j, maktaba ya Java ya kumbukumbu iliyo ndani ya bidhaa nyingi sana, uliomruhusu mshambulizi kuendesha msimbo kwenye seva kwa kuandikwa maandishi maalum kwenye logi zake.", "Ilionyesha hatari ya vitegemezi vilivyofichwa. Weka orodha ya vipengele vya programu (SBOM), tumia viraka haraka na tumia WAF na ufuatiliaji wakati wa kusasisha.")),
    T("solarwinds-attack", "SolarWinds attack", ["solarwinds", "solarwinds attack", "sunburst", "solarwinds hack"], "attacks", "software supply chain", {"fr": "Attaque SolarWinds", "sw": "Shambulio la SolarWinds", "rw": "Igitero cya SolarWinds"},
      ("A supply-chain attack discovered in 2020 in which attackers slipped malicious code into a genuine software update from a network-management vendor, which thousands of organisations then installed.", "It showed that trusted updates can be a path in. Defences: verify and sign builds, monitor software vendors' access, segment networks, watch for unusual outbound traffic and keep logs."),
      ("Une attaque de la chaîne d'approvisionnement découverte en 2020 : des pirates ont glissé du code malveillant dans une vraie mise à jour d'un éditeur de gestion de réseau, installée ensuite par des milliers d'organisations.", "Elle a montré qu'une mise à jour de confiance peut être une porte d'entrée. Défenses : vérifier et signer les builds, surveiller l'accès des fournisseurs, segmenter les réseaux, surveiller le trafic sortant inhabituel et conserver les journaux."),
      ("Igitero cyo mu murongo w'itangwa cy'ibikoresho cyavumbuwe muri 2020, aho abashimusi bashyize code mbi mu ivugurura nyaryo ry'ikigo gikora porogaramu zo gucunga imiyoboro, ryashyizweho n'ibigo ibihumbi.", "Cyerekanye ko ivugurura ryizewe rishobora kuba inzira yo kwinjira. Kwirinda: kugenzura no gusinya builds, gukurikirana uburenganzira bw'abatanga serivisi, gutandukanya imiyoboro, kureba ibisohoka bidasanzwe no kubika logs."),
      ("Shambulio la msururu wa ugavi lililogunduliwa 2020 ambapo wahalifu waliweka msimbo hasidi kwenye sasisho halali la muuzaji wa usimamizi wa mtandao, lililosakinishwa na maelfu ya mashirika.", "Lilionyesha sasisho linaloaminika linaweza kuwa njia ya kuingia. Ulinzi: kuhakiki na kusaini build, kufuatilia ufikiaji wa wauzaji, kutenga mitandao, kuangalia trafiki ya nje isiyo ya kawaida na kuweka logi.")),
    T("stuxnet", "Stuxnet", ["stuxnet", "stuxnet worm", "industrial sabotage malware"], "malware", "industrial control system", {"fr": "Stuxnet", "sw": "Stuxnet", "rw": "Stuxnet"},
      ("A highly sophisticated worm discovered in 2010 that targeted industrial control systems and is widely reported to have damaged centrifuges in Iran. It showed that malware can cause physical damage.", "It is the standard example of cyber-physical attacks. Industrial sites defend with air gaps, segmentation, strict USB control, application allow-listing and monitoring of control networks."),
      ("Un ver extrêmement sophistiqué découvert en 2010, visant des systèmes de contrôle industriels, dont on rapporte largement qu'il a endommagé des centrifugeuses en Iran. Il a montré qu'un logiciel malveillant peut causer des dégâts physiques.", "C'est l'exemple classique des attaques cyber-physiques. Les sites industriels se défendent par isolement réseau, segmentation, contrôle strict des clés USB, liste blanche d'applications et surveillance des réseaux de contrôle."),
      ("Worm ikomeye cyane yavumbuwe muri 2010 yibasiye sisitemu zigenzura inganda, kandi biravugwa cyane ko yangije centrifuges muri Iran. Yerekanye ko malware ishobora gutera ibyangiritse ku mubiri.", "Ni urugero rw'ingenzi rw'ibitero bihuza cyber n'ibikoresho. Inganda zirinda zikoresheje air gap, gutandukanya imiyoboro, kugenzura USB, urutonde rw'porogaramu zemewe no gukurikirana imiyoboro igenzura."),
      ("Worm ya kisasa sana iliyogunduliwa 2010 iliyolenga mifumo ya udhibiti wa viwanda, na inaripotiwa sana kuwa iliharibu centrifuges nchini Iran. Ilionyesha programu hasidi inaweza kusababisha uharibifu wa kimwili.", "Ni mfano wa kawaida wa mashambulizi ya mtandao-kimwili. Viwanda hujilinda kwa air gap, kutenga mitandao, udhibiti mkali wa USB, orodha ya programu zinazoruhusiwa na kufuatilia mitandao ya udhibiti.")),
    T("pegasus-spyware", "Pegasus spyware", ["pegasus", "pegasus spyware", "nso pegasus", "zero click spyware"], "malware", "smartphone security", {"fr": "Logiciel espion Pegasus", "sw": "Spyware ya Pegasus", "rw": "Spyware ya Pegasus"},
      ("Commercial spyware reported to infect phones, sometimes with no click at all (zero-click), to read messages, record calls and track location. It has been reported mainly against journalists, activists and officials.", "For most people the risk is low, but high-risk users should keep phones updated, restart often, consider Lockdown Mode on iPhone, and seek expert help (for example from digital-rights organisations) if they suspect it."),
      ("Un logiciel espion commercial qui infecterait les téléphones, parfois sans aucun clic (zero-click), pour lire les messages, enregistrer les appels et suivre la position. Il a surtout été signalé contre des journalistes, militants et responsables.", "Pour la plupart des gens le risque est faible, mais les personnes exposées doivent mettre à jour leur téléphone, le redémarrer souvent, envisager le mode Isolement sur iPhone et demander l'aide d'experts (organisations de droits numériques) en cas de doute."),
      ("Spyware y'ubucuruzi ivugwa ko yandurisha telefone, rimwe na rimwe nta gukanda na kimwe (zero-click), igasoma ubutumwa, ikandika guhamagara ikanamenya aho uri. Yavuzwe cyane ku bakora itangazamakuru, abaharanira uburenganzira n'abayobozi.", "Ku bantu benshi ibyago ni bike, ariko abafite ibyago byinshi bagomba kuvugurura telefone, kuyizimya ikongera gucura kenshi, gukoresha Lockdown Mode kuri iPhone no gusaba ubufasha bw'impuguke nibakeka ko banduye."),
      ("Spyware ya kibiashara inayoripotiwa kuambukiza simu, wakati mwingine bila kubofya chochote (zero-click), kusoma ujumbe, kurekodi simu na kufuatilia eneo. Imeripotiwa zaidi dhidi ya waandishi, wanaharakati na maafisa.", "Kwa watu wengi hatari ni ndogo, lakini walio hatarini wanapaswa kusasisha simu, kuiwasha upya mara kwa mara, kufikiria Lockdown Mode kwenye iPhone na kutafuta msaada wa wataalamu wakishuku.")),
    T("emotet", "Emotet", ["emotet", "emotet malware", "emotet botnet"], "malware", "email with malicious attachment", {"fr": "Emotet", "sw": "Emotet", "rw": "Emotet"},
      ("A banking-trojan-turned-delivery-service that spread through convincing replies to real email threads with infected attachments, then installed other malware such as ransomware.", "Be careful with unexpected attachments even in a familiar conversation. Disable Office macros from the internet, filter email and confirm odd attachments with the sender by phone."),
      ("Un cheval de Troie bancaire devenu service de livraison de logiciels malveillants, qui se propageait par de faux messages dans de vraies conversations e-mail avec des pièces jointes infectées, puis installait d'autres malwares comme des rançongiciels.", "Méfiez-vous des pièces jointes inattendues même dans une conversation connue. Désactivez les macros Office venant d'internet, filtrez le courrier et confirmez par téléphone les pièces étranges."),
      ("Trojan ya banki yahindutse serivisi yo gutanga malware, yakwirakwiraga mu bisubizo bisa neza mu mashusho nyayo y'imeri biriho attachments zanduye, hanyuma igashyiraho izindi malware nka ransomware.", "Ujye witonda attachments utiteze nubwo ziri mu biganiro uzi. Hagarika macros za Office ziva kuri interineti, ushungure imeri kandi wemeze attachments zidasanzwe n'uwohereje kuri telefone."),
      ("Trojan ya benki iliyogeuka huduma ya kusambaza programu hasidi, iliyoenea kupitia majibu ya kushawishi ndani ya mazungumzo halisi ya barua pepe yenye viambatisho vilivyoambukizwa, kisha kusakinisha programu nyingine kama ransomware.", "Kuwa makini na viambatisho usivyotarajia hata katika mazungumzo unayoyajua. Zima macros za Office kutoka mtandaoni, chuja barua pepe na uthibitishe viambatisho vya ajabu kwa simu.")),
]
